-- Default country: IND when applicable.

WITH srp_deduped AS ( SELECT CAST(DATE_TRUNC('day', at_timezone(s.__time, 'Asia/Kolkata')) AS DATE) AS doi, s.mri_session_id, s.route_id, s.user_type, s.os, s.channel, CASE WHEN s.channel_exp_info IS NULL THEN 'null' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V0') THEN 'V0' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V1') THEN 'V1' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V2') THEN 'V2' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V3') THEN 'V3' WHEN contains(s.channel_exp_info, 'COHORT_DEALS_SRP_AB:V4') THEN 'V4' ELSE 'others' END AS exp_Variant, CASE WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 THEN '0. Same Day' -- AND HOUR(DATE_ADD('MINUTE', 330, s."__time")) <= 17 THEN '0. LMB Same Day' -- WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 0 -- AND HOUR(DATE_ADD('MINUTE', 330, s."__time")) > 17 THEN '0. non-LMB Same Day' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 1 THEN '1. DBD 1' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' WHEN DATE_DIFF('day', DATE(DATE_ADD('MINUTE', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' ELSE 'Others' END AS search_day, CAST(s.doj AS VARCHAR) AS doj, -- s.src_id, s.dest_id, MIN(s.offset + s.position + 1) AS position, MAX(CASE WHEN s.cohort_type = 'BOOSTUI' THEN 1 ELSE 0 END) AS boostui_seen FROM "user_interaction"."search_route_details" s LEFT JOIN "user_interaction"."search_details" d ON s.__time = d.__time AND s.mri_session_id = d.mri_session_id WHERE s.__time >= TIMESTAMP '2026-04-11 18:30:00' AND s.__time < TIMESTAMP '2026-04-17 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.channel IN ('MOBILE_APP') AND d.is_filter_applied = FALSE and d.sort < 1 AND s.operator_id NOT IN (10244, 10283, 10823, 11044, 11060, 15129, 15130, 15443, 15447, 15499, 16081, 16124, 16227, 16374, 16426, 16580, 16647, 16777, 16884, 17012, 17101, 17889, 18101, 18115, 18237, 18491, 19393, 19502, 24978, 25187, 25946, 26936, 27000, 27455, 28011, 29176, 29479, 3030, 6392, 7115, 8065) -- AND s.os = 'Android' -- AND s.os = 'iOS' -- AND CAST(src_id AS VARCHAR) || '-' || CAST(dest_id AS VARCHAR) IN ('122-123') AND s.country = 'IND' GROUP BY 1,2,3,4,5,6,7,8,9 ), boosted_sessions AS ( SELECT DISTINCT mri_session_id FROM srp_deduped s WHERE boostui_seen = 1 ), sl_deduped AS ( SELECT mri_session_id, route_id, doj, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-04-11 18:30:00' AND __time < TIMESTAMP '2026-04-17 18:30:00' -- AND os = 'Android' AND country = 'IND' GROUP BY 1,2,3 ), confirm_deduped AS ( SELECT mri_session_id, route_id, tin, CAST(doj AS VARCHAR) AS doj, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-04-11 18:30:00' AND __time < TIMESTAMP '2026-04-17 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND country = 'IND' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2,3,4 ) SELECT -- CASE WHEN srp.doi >= DATE '2026-01-01' AND srp.doi < DATE '2026-01-07' THEN 'Pre DBS' -- WHEN srp.doi >= DATE '2026-01-07' AND srp.doi < DATE '2026-01-28' THEN CAST(srp.doi AS VARCHAR) -- ELSE 'Other Period' END AS doi, -- 'All India' AS route_cohort, -- UPPER(srp.user_type) AS user_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, 'Boosted all versions' AS user_type, search_day AS DBD, -- 'Any day' AS DBD, COUNT(DISTINCT srp.mri_session_id) all_srp_sessions, COUNT(DISTINCT sl.mri_session_id) all_sl_lands, COUNT(DISTINCT c.mri_session_id) overall_confirm_sessions, COUNT(DISTINCT c.tin) overall_confirm_tins, COUNT(DISTINCT CASE WHEN srp.position = 1 THEN sl.mri_session_id END) AS Top_Tuple_sl_land_sessions, COUNT(DISTINCT CASE WHEN srp.position = 1 THEN c.mri_session_id END) AS Top_Tuple_confirm_sessions, COUNT(DISTINCT CASE WHEN srp.position = 1 THEN c.tin END) AS Top_Tuple_tins, COUNT(DISTINCT CASE WHEN srp.position <= 5 THEN sl.mri_session_id END) AS Top_5_Tuple_sl_land_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 5 THEN c.mri_session_id END) AS Top_5_Tuple_confirm_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 5 THEN c.tin END) AS Top_5_Tuple_tins, COUNT(DISTINCT CASE WHEN srp.position <= 10 THEN sl.mri_session_id END) AS Top_10_Tuple_sl_land_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 10 THEN c.mri_session_id END) AS Top_10_Tuple_confirm_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 10 THEN c.tin END) AS Top_10_Tuple_tins, COUNT(DISTINCT CASE WHEN srp.position <= 15 THEN sl.mri_session_id END) AS Top_15_Tuple_sl_land_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 15 THEN c.mri_session_id END) AS Top_15_Tuple_confirm_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 15 THEN c.tin END) AS Top_15_Tuple_tins, COUNT(DISTINCT CASE WHEN srp.position <= 20 THEN sl.mri_session_id END) AS Top_20_Tuple_sl_land_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 20 THEN c.mri_session_id END) AS Top_20_Tuple_confirm_sessions, COUNT(DISTINCT CASE WHEN srp.position <= 20 THEN c.tin END) AS Top_20_Tuple_tins FROM srp_deduped srp -- INNER JOIN boosted_sessions bs ON bs.mri_session_id = srp.mri_session_id AND srp.os = 'iOS' LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id AND srp.doj = sl.doj LEFT JOIN confirm_deduped c ON srp.mri_session_id = c.mri_session_id AND srp.route_id = c.route_id AND srp.doj = c.doj -- WHERE srp.exp_Variant = 'V2' GROUP BY 1,2,3 -- ,4,5 ORDER BY 3
